Overview On HiCom, manually clicking to download and organize data is not easy. This introduces a method to retrieve data by supplying a URL that specifies the selection criteria.
Code HTTP.jl 1 for y = 2019:2024 url = replace(&#34;https://ncss.hycom.org/thredds/ncss/GLBy0.08/expt_93.0/ts3z/$y?var=water_temp &amp;north=36.88 &amp;west=129.52 &amp;east=130.24 &amp;south=36.32 &amp;disableProjSubset=on &amp;horizStride=1 &amp;time_start=$y-01-01T00%3A00%3A00Z &amp;time_end=$y-12-31T21%3A00%3A00Z &amp;timeStride=1 &amp;vertCoord=0 &amp;accept=netcdf4&#34;, &#39;\n&#39; =&gt; &#34;&#34;, &#34; &#34; =&gt; &#34;&#34;) @time response = HTTP.get(url) open(&#34;data_$y.nc4&#34;, &#34;w&#34;) do f write(f, response.body) end end For example, the above code fetches sea surface temperature (SST, Sea Surface Temperature) at three-hour intervals for experiment number 93 of GLBy0.08, over the period 2019–2024, within the latitude range 36.32–36.88 and longitude range 129.52–130.24.
NCDatasets.jl 2 data_ = [] for y = 2019:2024 ds = NCDataset(&#34;data_$y.nc4&#34;) push!(data_, DataFrame([ds[&#34;time&#34;][:] reshape(ds[&#34;water_temp&#34;][:, :, 1, :], 150, :)&#39;], [&#34;t&#34;; repeat(&#34;i&#34; .* string.(1:10), outer = 15) .* repeat(&#34;j&#34; .* string.(1:15), inner = 10)])) close(ds) end The downloaded file is a *.nc4 file, i.e., NetCDF-4 (Network Common Data Form version 4). Although it is widely used for handling high-dimensional data, in this guide we create a DataFrame using DataFrames.jl.
Saving _data_ = vcat(data_...) _data_.t = Date.(_data_.t) _data_ = combine(groupby(_data_, :t), names(_data_, Not(:t)) .=&gt; mean .=&gt; names(_data_, Not(:t))) CSV.write(&#34;data_GLBy0.08_expt_93.0.csv&#34;, _data_) tnsr = reshape(Matrix(_data_[:, 2:end])&#39;, 10, 15, :) @save &#34;data_tnsr.jld2&#34; tnsr # @load &#34;data_tnsr.jld2&#34;; tnsr You can save tensors as-is using JLD2.jl, or save them in an easy-to-write format using CSV.jl.
Full code using HTTP, NCDatasets, DataFrames, Dates, CSV, JLD2, StatsBase for y = 2019:2024 url = replace(&#34;https://ncss.hycom.org/thredds/ncss/GLBy0.08/expt_93.0/ts3z/$y?var=water_temp &amp;north=36.88 &amp;west=129.52 &amp;east=130.24 &amp;south=36.32 &amp;disableProjSubset=on &amp;horizStride=1 &amp;time_start=$y-01-01T00%3A00%3A00Z &amp;time_end=$y-12-31T21%3A00%3A00Z &amp;timeStride=1 &amp;vertCoord=0 &amp;accept=netcdf4&#34;, &#39;\n&#39; =&gt; &#34;&#34;, &#34; &#34; =&gt; &#34;&#34;) @time response = HTTP.get(url) open(&#34;data_$y.nc4&#34;, &#34;w&#34;) do f write(f, response.body) end end # ds = NCDataset(&#34;data_$y.nc4&#34;) # # ds.attrib # # keys(ds) # # ds[&#34;water_temp&#34;][:, :, 1, :] # CSV.write(&#34;lon.csv&#34;, DataFrame(i = 1:10, x = round.(ds[&#34;lon&#34;][:], digits = 2))) # CSV.write(&#34;lat.csv&#34;, DataFrame(j = 1:15, y = round.(ds[&#34;lat&#34;][:], digits = 2))) # close(ds) data_ = [] for y = 2019:2024 ds = NCDataset(&#34;data_$y.nc4&#34;) push!(data_, DataFrame([ds[&#34;time&#34;][:] reshape(ds[&#34;water_temp&#34;][:, :, 1, :], 150, :)&#39;], [&#34;t&#34;; repeat(&#34;i&#34; .* string.(1:10), outer = 15) .* repeat(&#34;j&#34; .* string.(1:15), inner = 10)])) close(ds) end _data_ = vcat(data_...) _data_.t = Date.(_data_.t) _data_ = combine(groupby(_data_, :t), names(_data_, Not(:t)) .=&gt; mean .=&gt; names(_data_, Not(:t))) CSV.write(&#34;data_GLBy0.08_expt_93.0.csv&#34;, _data_) tnsr = reshape(Matrix(_data_[:, 2:end])&#39;, 10, 15, :) @save &#34;data_tnsr.jld2&#34; tnsr # @load &#34;data_tnsr.jld2&#34;; tnsr Niño 3.4 The following code retrieves the average sea surface temperature for the Niño 3.4 region3, defined as latitude 5°S–5°N and longitude 170°W–120°W.
