u + 1 } \over { 2 }} ight) } \over { \sqrt{
u \pi} \Gamma \left( {{ 
u } \over { 2 }} ight) }} \left( 1 + {{ x^{2} } \over { 
u }} ight)^{- {{ 
u + 1 } \over { 2 }}} \cdot {{ 1 } \over { x }} \end{align*} $$
Relation between the Beta Function and the Gamma Function: $$ B(p,q) = {{\Gamma (p) \Gamma (q)} \over {\Gamma (p+q) }} $$
According to Euler&rsquo;s Reflection Formula, $\sqrt{\pi} = \Gamma (1/2)$, and based on the abovementioned lemma, $$  egin{align*} f_{Y}(y) =&amp; {{ \Gamma \left( {{ 
u + 1 } \over { 2 }} ight) } \over { \Gamma (1/2) \Gamma \left( {{ 
u } \over { 2 }} ight) }} {{ 1 } \over { \sqrt{
u} }} \left( 1 + {{ x^{2} } \over { 
